Considering that this is only occurring on the web, is this happening outside of flutter?

I seem to have addressed this issue in my project (Flutter web canvaskit running in mobile Safari) by NOT calling requestFocus() on the input field programmatically when running in a mobile browser. 

There was effectively a double call happening on mobile web that caused the field to move up as if there were two keyboards visible.

I'm still calling requestFocus() on desktop web (where it makes sense), but on mobile web it does not, thus the undesired outcome.

Offering this here with the hope it helps some of you who arrive on this thread...

Here's the change:

_old version_
```dart
WidgetsBinding.instance.addPostFrameCallback((_) {
   FocusScope.of(context).requestFocus(_inputFocusNode);
});
```

_new version_
```dart
if (UniversalPlatform.isWeb && web.isMobileDevice()) {
   // DO NOT REQUEST FOCUS
} else {
   // REQUEST FOCUS
   WidgetsBinding.instance.addPostFrameCallback((_) {
      FocusScope.of(context).requestFocus(_inputFocusNode);
   });
}
```

isMobileDevice() is defined in a `platform_web.dart` file like this:

```dart
bool isMobileDevice() {
  final userAgent = html.window.navigator.userAgent.toLowerCase();
  return userAgent.contains('mobi') ||
      userAgent.contains('android') ||
      userAgent.contains('iphone') ||
      userAgent.contains('ipad') ||
      userAgent.contains('ipod');
}
```

Also, you'll want to confirm in a variety of scenarios whether this approach really works for you (eg. hardware keyboard attached to an iPad).

I found a fix! this seems to be a pretty broad issue, so this will definitely not apply to most, but here was my problem:

I was initializing my formKey within my build method:

```
@override
Widget build(BuildContext context) {
   final formKey = GlobalKey<FormState>();
  return Form(key: formKey,
  // rest of code
}
```

The issue was due to the GlobalKey<FormState> being recreated every time the build method runs. if you create a GlobalKey inside the build method, it gets recreated on every rebuild, which can cause the form to lose its state and focus, leading to the keyboard dismissing unexpectedly. moved it outside the build method and it totally fixed my issue.

If someone needs solution that just works. You can use widget below. It solves several problems, scroll to focused field and prevents white space at bottom of page.

**Important** For android it works only inside **HTTPS** context. It is requirement of Virtual Keyboard API.

**Important** Scaffold resizeToAvoidBottomInset must be false

Wrap any scrollable widget such as SingleChildScrollView, CustomScrollView etc

Example of usage:

```dart
AutoscrollContainer(
  builder: (context, scrollController, bottomInset) =>
      SingleChildScrollView(
    controller: scrollController,
    child: Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        ...yourWidgets,
        SizedBox(height: bottomInset),
      ],
    ),
  ),
);
```

```dart
import 'dart:js_interop';
import 'dart:js_interop_unsafe';
import 'dart:math';

import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';
import 'package:web/web.dart';

class AutoscrollContainer extends StatefulWidget {
  final ScrollController? scrollController;

  final Widget Function(
    BuildContext context,
    ScrollController controller,
    double bottomInset,
  ) builder;

  const AutoscrollContainer({
    super.key,
    this.scrollController,
    required this.builder,
  });

  @override
  State<AutoscrollContainer> createState() => _AutoscrollContainerState();
}

class _AutoscrollContainerState extends State<AutoscrollContainer> {
  static const _scrollDuration = Duration(milliseconds: 300);

  late final JSFunction _iosResizeCallback;
  late final JSFunction _resizeCallback;
  late final ScrollController _scrollController;
  var _keyboardHeight = 0.0;
  var _bottomInset = 0.0;

  @override
  void initState() {
    if (defaultTargetPlatform == TargetPlatform.android &&
        window.navigator.hasProperty('virtualKeyboard'.toJS).toDart &&
        !window.navigator
            .getProperty<JSObject>('virtualKeyboard'.toJS)
            .getProperty<JSBoolean>('overlaysContent'.toJS)
            .toDart) {
      window.navigator
          .getProperty<JSObject>('virtualKeyboard'.toJS)
          .setProperty('overlaysContent'.toJS, true.toJS);
    }

    if (window.visualViewport?.height != null) {
      final height = window.visualViewport!.height;

      _iosResizeCallback = (() {
        final focusedContext = FocusManager.instance.primaryFocus?.context;
        if (focusedContext == null ||
            focusedContext
                    .findAncestorStateOfType<_AutoscrollContainerState>() ==
                null ||
            !mounted) return;

        if (window.visualViewport!.height < height) {
          _keyboardHeight = window.innerHeight - window.visualViewport!.height;
          scrollToFocusedObject();
          setState(
            () => _bottomInset = height - window.visualViewport!.height,
          );
        } else {
          FocusManager.instance.primaryFocus?.unfocus();
          setState(() => _bottomInset = 0);
        }
      }).toJS;

      _resizeCallback = ((JSObject event) {
        var boundingRect = event
            .getProperty<JSObject>('target'.toJS)
            .getProperty<JSObject>('boundingRect'.toJS);
        _keyboardHeight =
            boundingRect.getProperty<JSNumber>('height'.toJS).toDartDouble;
        scrollToFocusedObject();
        setState(() => _bottomInset = _keyboardHeight);
      }).toJS;

      if (defaultTargetPlatform == TargetPlatform.android &&
          window.navigator.hasProperty('virtualKeyboard'.toJS).toDart) {
        window.navigator
            .getProperty<JSObject>('virtualKeyboard'.toJS)
            .callMethod(
              'addEventListener'.toJS,
              'geometrychange'.toJS,
              _resizeCallback,
            );
      } else {
        window.visualViewport?.addEventListener('resize', _iosResizeCallback);
      }
    }
    _scrollController = widget.scrollController ?? ScrollController();

    super.initState();
  }

  @override
  void dispose() {
    window.visualViewport?.removeEventListener('resize', _iosResizeCallback);
    if (defaultTargetPlatform == TargetPlatform.android &&
        window.navigator.hasProperty('virtualKeyboard'.toJS).toDart) {
      window.navigator.getProperty<JSObject>('virtualKeyboard'.toJS).callMethod(
            'removeEventListener'.toJS,
            'geometrychange'.toJS,
            _resizeCallback,
          );
    }

    if (_scrollController != widget.scrollController) {
      _scrollController.dispose();
    }
    super.dispose();
  }

  void scrollToFocusedObject() {
    final focusedContext = FocusManager.instance.primaryFocus?.context;
    if (focusedContext == null ||
        focusedContext.findAncestorStateOfType<_AutoscrollContainerState>() ==
            null ||
        !mounted) return;

    setState(() => _bottomInset = _keyboardHeight);

    final box = focusedContext.findRenderObject() as RenderBox;
    final position = box.localToGlobal(Offset.zero).dy;
    final height = box.size.height + 24;
    final screenHeight = MediaQuery.of(context).size.height;
    final topDistance = screenHeight - height - position;
    final shift = max(0.0, _keyboardHeight - topDistance);

    WidgetsBinding.instance.addPostFrameCallback((timeStamp) {
      _scrollController.animateTo(
        _scrollController.offset + shift,
        duration: _scrollDuration,
        curve: Curves.easeInOut,
      );
    });
  }

  @override
  Widget build(BuildContext context) =>
      widget.builder(context, _scrollController, _bottomInset);
}
```

I believe the work around in this link is connected to this issue https://participant54.com/flutter-keyboard-issues-fix-ios-android-and-web/ the issue being 

The iOS keyboard has a Done button in the toolbar.
There’s another Done button at the bottom-right of the keyboard.
The top Done button hides the keyboard but doesn’t unfocus the text field.
Now when you reopen the keyboard while the textfield is still in focus(cursor blinking), extra spacing is added.

Is there any way to detect the keyboard without implementing this? I'd rather not have to check the insets to see if the keyboard is visible 

`///A Mixin to be applied to a type T that EXTENDS a stateful widget ON State of type T AND WidgetsBindingObserver. Use it to solve Flutter keyboard issues in iOS Web.
mixin iOSKeyboardInsetUtil<T extends StatefulWidget>
    on State<T>, WidgetsBindingObserver {

  bool _isKeyboardVisible = false;

  //1. Only apply if the app is running on (web AND iOS)
  bool get isIOSWeb {
    return kIsWeb && TargetPlatform.iOS == defaultTargetPlatform;
  }

  @override
  void initState() {
    super.initState();
    //2. Listen to WidgetsBinding for didChangeMetrics below
    if (isIOSWeb) {
      WidgetsBinding.instance.addObserver(this);
    }
  }

  @override
  void dispose() {
    if (isIOSWeb) {
      WidgetsBinding.instance.removeObserver(this);
    }
    super.dispose();
  }

  @override
  void didChangeMetrics() {
    //3. Listen to didChangeMetrics and detect the keyboard hide/show state via viewInsets.bottom.
    super.didChangeMetrics();
    if (isIOSWeb) {
      final bottomInset = View.of(context).viewInsets.bottom;

      //4. Store keyboard "opened" state based on the condition that viewInsets.bottom >0
      final newKeyboardState = bottomInset > 0;

      //5. Update the _isKeyboardVisible and use it in your parent widget if needed.
      if (_isKeyboardVisible != newKeyboardState) {
        setState(() {
          _isKeyboardVisible = newKeyboardState;
        });

        if (!newKeyboardState) {
          //6. If newKeyboardState is false(keyboard is hidden), unfocus from the widget.
          FocusScope.of(context).requestFocus(FocusNode());
        }
      }
    }
  }

  bool get isKeyboardVisible => _isKeyboardVisible;
}`

I encountered this issue on Android Web, but the fix is the same as https://github.com/flutter/flutter/issues/124205#issuecomment-3206581098

The issue occurs when the keyboard is opened on a Textfield that is already focused. resizeToAvoidBottomInset does not help, and the issue appears independent of the Textfield's location (be it popup, the main screen, etc).

The solution is to assign the Textfield a FocusNode and manually remove focus after the keyboard is closed.

```dart
class WebTextFieldFix extends StatefulWidget {
  const WebTextFieldFix({super.key});

  @override
  State<WebTextFieldFix> createState() => _WebTextFieldFixState();
}

class _WebTextFieldFixState extends State<WebTextFieldFix> with WidgetsBindingObserver {
  final focusNode = FocusNode();
  bool _keyboardVisible = false;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) _checkKeyboardVisibility();
    });
  }

  @override
  void dispose() {
    focusNode.dispose();
    WidgetsBinding.instance.removeObserver(this);
    super.dispose();
  }

  @override
  void didChangeMetrics() {
    super.didChangeMetrics();
    _checkKeyboardVisibility();
  }

  void _checkKeyboardVisibility() {
    final keyboardVisible = View.of(context).viewInsets.bottom > 0.0;
    if (keyboardVisible != _keyboardVisible) {
      _keyboardVisible = keyboardVisible;
      if (!keyboardVisible) {
        focusNode.unfocus();
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    return TextField(focusNode: focusNode);
  }
}
```

